// === Tab: mySketch ===
//Code by Aaron Reuland

colors = ["#82964e", "#567963", "#a7f7f7", "#5981a5", "#264b5d", "#323227"]

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	noStroke()
	let c = random(colors.length - 1)
	let coloring = drawingContext.createLinearGradient(0, height / 2, width * 0.67, height / 2)
	coloring.addColorStop(0, colorMixer(c, colors))
	coloring.addColorStop(0.5, colorMixer(c + 0.7, colors))
	coloring.addColorStop(0.9, colorMixer(c + 1, colors))
	coloring.addColorStop(1, colorMixer(c + 1.25, colors))
	drawingContext.fillStyle = coloring
	rect(0, 0, width, height)

	form(1)
	for (let i = 0; i < 8; i++) {
		form(random(0.6))
	}

	let g = get(0, 0, width * 0.66, height)
	 g.filter(BLUR, 2, false)

	imageMode(CENTER)
	push()
	translate(width * 0.66 + (width * 0.33 / 2), height / 2)
	scale(-1, 1)
	image(g, 0, 0, width * 0.35, height)
	pop()
	stroke(255, 20)
	strokeWeight(0.5)
	let mover=1.1
	for(let x=width*0.655; x<width; x+=mover){
		line(x, 0, x, height)
		 mover= pow(mover, 1.04)
	}
}


function colorMixer(c, colorArray) {
	let c1 = floor(c % colorArray.length)
	let c2 = floor(c + 1) % colorArray.length
	let color1 = colorArray[c1]
	let color2 = colorArray[c2]
	let mix = fract(c)
	var coloring = color(spectral.mix(color1, color2, mix))
	return coloring
}


function form(scaler) {
	push()
	let sinOff = random(TAU)
	let newC = random(0.1, colors.length - 1.4)
	let finalX = width * 0.63 * scaler
	let xInc = width / 50 * scaler

	let startH = height * 0.5 * scaler
	let finalH = height * 0.1 * scaler
	let ystartOffAmount = map(scaler, 0.1, 1, height * 0.5, 0)
	let ystartOff = random(-ystartOffAmount, ystartOffAmount)
	let w = width * 0.1 * scaler
	let blurOff = -w * scaler
	let shadowBlur = w * 2 * scaler
	for (let x = 0; x < finalX; x += xInc) {
		let h = map(x, 0, finalX, startH, finalH)
		fill(colorMixer(newC, colors))
		newC += 0.1
		//let sinScale= x/((width/6)*scaler/2)
		yoff = sin(sinOff + x / (width / 6)) * height / 10
		push()
		translate(0, ystartOff)
		for (let i = 0; i < 100; i++) {
			//	blendMode(DODGE)
			push()
			var c = colorMixer(newC - 0.1, colors)
			c.setAlpha(180)
			fill(c)
			let pxoff = abs(randomGaussian(width / 60, width / 20))
			let pyoff = random(-h / 2, h / 2)


			ellipse(x - pxoff, height / 2 + pyoff + (yoff / 2), random(4) * scaler)

			pop()
		}
		push()
		drawingContext.shadowOffsetX = blurOff;
		drawingContext.shadowOffsetY = 0;
		drawingContext.shadowBlur = shadowBlur;
		drawingContext.shadowColor = colorMixer(newC - 0.2, colors);
		ellipse(x, height / 2 + yoff, h, h)
		pop()
		pop()
	}
	pop()
}

